import statistics


def prevoir(xs, ys, x):
    if not min(xs) <= x <= max(xs):
        raise ValueError("extrapolation refusée")
    mx, my = statistics.mean(xs), statistics.mean(ys)
    a = sum((u - mx) * (v - my) for u, v in zip(xs, ys)) / sum((u - mx) ** 2 for u in xs)
    b = my - a * mx
    return round(a * x + b, 1)
